//! Logic of the ldn-tunnel Tesla overlay, linked into the C++ overlay (overlay/) as a
//! staticlib: the `ldnt:cfg` client ([`cfg`], types shared with the module through
//! `ldn_tunnel_core::cfg_types`), the status texts ([`text`]), saving and the module restart
//! sequence ([`app`]). The Tesla/Ultrahand screens stay C++ and call the C ABI in `ffi`
//! (header: include/ldn_tunnel_overlay.h, generated by cbindgen); libnx calls are C
//! (overlay/source/platform.c).
//!
//! `no_std`, no allocator. Built for `aarch64-unknown-none` (Makefile `overlay-rs`); host builds
//! (tests, crates/ipc-tests) never call `ffi`, so the linker drops it with its C imports.
#![no_std]

#[cfg(not(target_os = "none"))]
extern crate std;

pub mod app;
pub mod cfg;
pub mod text;

mod ffi;

#[cfg(test)]
#[allow(
    clippy::indexing_slicing,
    clippy::unwrap_used,
    clippy::arithmetic_side_effects
)]
mod tests;
